//! Complete persistence/restart examples are discoverable without source or project docs.
use serde_json::{Value, json};

pub fn get() -> Value {
    json!({
        "format":"Canonical slimeybeats-studio version 2: immutable Float32 source pool with hashes, clip/lane/scoped-EQ metadata, original/before recipes, and retained Undo/Redo. It needs neither a master nor a legacy Studio preview, original library files, plugins or model runtime to reopen.",
        "identity":"Retain the opaque project_id returned by a successful save/handoff job. It survives companion restarts with the SAME configured output root. It is not a path, session_id, preview_id or portable file locator. Foreign output-root IDs and caller-supplied source/output/executable paths are rejected. Do not edit ownership receipts or manifests.",
        "save":{"tool":"save_arrangement_project","arguments":{"session_id":"<current session_id from get_arrangement>","expected_revision":2},
            "read":"Substitute the latest numeric revision. Poll get_job_status with the returned job_id every 250–1000 ms until terminal. completed.result contains project_id, relative project_path, manifest_identity, format and version. Each save creates a new folder; previous projects and source files are preserved. Save is a project persistence action, not export_arrangement."},
        "restart_reopen":{"tool":"load_arrangement_project","arguments":{"project_id":"<retained project_id>"},
            "read":"On a fresh connection or after clear_session, omit both replacement fields. Poll the job. completed.result contains the NEW session_id/revision, full metadata/assets/history and preview:null. Do not reuse an old session_id after reopening. No whole-song rendering, playback or desktop launch occurs."},
        "replace_open_workspace":{"tool":"load_arrangement_project","arguments":{"project_id":"<retained project_id>","replace_session_id":"<current session_id from get_arrangement>","expected_revision":2},
            "read":"When another arrangement is open, provide BOTH current replacement ID and latest numeric revision. Stale/incomplete guards, corrupt hashes, links, invalid geometry/history or budget failures preserve the prior workspace and preview. Cancellation before adoption also preserves it. The master/source/legacy Studio bank are separate and are not replaced."},
        "desktop":{"tool":"open_arrangement_in_desktop","arguments":{"session_id":"<current session_id from get_arrangement>","expected_revision":2},
            "read":"Only when the user explicitly requests opening the arrangement AND get_capabilities.desktop_configured is true. Configuration is detection, not compatibility: even an identical engine/version/build label may refer to an older v1-only installed app. This tool lazily probes --studio-project-capabilities (8 KiB stdout, 3 seconds, cancellable), requiring format slimeybeats-desktop-project-capabilities/version1, studio_project_versions including2, arrangement_live_editing:true and autoplay_on_project_open:false BEFORE saving. Old, incomplete, malformed, oversized or timed-out replies fail without project folders; build or install the matching preview and configure --desktop-exe to it. Only after compatibility succeeds, saves a new v2 project and invokes --studio-session. Poll for project_id, desktop_capabilities, desktop_launched, process_id and warning. No caller paths, final mix export or autoplay. Desktop/MCP edits are independent. Discovery, save-only, reopen and legacy desktop tools do not run this probe; a later launch failure retains the completed project with a warning."},
        "next":"After reopening, use current session_id/revision for edits, undo/redo, explicit render_arrangement audition preparation, or explicitly requested export_arrangement. To hand that reopened recipe to the GUI, call open_arrangement_in_desktop with its new current IDs.",
        "cancellation":"One heavy job at a time. Wait for terminal status before retrying. cancel_job is cooperative. Cancellation/staleness before project publication or load adoption preserves prior state; a project already durably saved remains reported as completed, with its project_id. A late cancellation prevents desktop launch when it has not already occurred.",
        "limits":"Per-source decoded bytes follow max_decoded_input_mib; aggregate sources follow the arrangement decoded-pool budget (input limit times eight, capped at 4 GiB). Shared manifest/history/layout and canonical WAV hash checks apply. These are admission limits, not a guarantee of total process RAM or available disk space.",
        "legacy":"save_studio_project/open_studio_in_desktop persist the separate legacy Studio preview. They do not save the Tracks recipe. Use these arrangement project tools for clips and scoped EQ."
    })
}
